  const [submitted, setSubmitted] = useState(false);

  const validate = (vals) => {
    const errs = {};
    if (!vals.fullName.trim()) {
      errs.fullName = "Full name is required.";
    } else if (vals.fullName.trim().length < 2) {
      errs.fullName = "Please enter your full name.";
    }

    if (!vals.email.trim()) {
      errs.email = "Email address is required.";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(vals.email.trim())) {
      errs.email = "Please enter a valid email address.";
    }

    if (vals.phone.trim()) {
      const digits = vals.phone.replace(/\D/g, "");
      if (!/^[+\d\s().-]+$/.test(vals.phone) || digits.length < 7 || digits.length > 15) {
        errs.phone = "Please enter a valid phone number (e.g. +1 555-123-4567).";
      }
    }
    return errs;
  };

