              </span>
            )}
          </div>

          <button type="submit" className="submit-btn">Send message</button>

          {success && (
            <div className="success-banner" role="status">
              Thanks! Your message has been sent.
            </div>
          )}
        </form>
      </div>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<ContactForm />);
